```python
import time
import threading

class Lift:
    def __init__(self, name):
        self.name = name
        self.position = 0
        self.speed = 1

    def move(self, direction):
        if direction == 'up':
            self.position += self.speed
        elif direction == 'down':
            self.position -= self.speed
        print(f"{self.name} is moving to position {self.position}")

class Skyscraper:
    def __init__(self):
        self.lifts = []
        self.floor_count = 100

    def add_lift(self, name):
        self.lifts.append(Lift(name))

    def start_simulation(self):
        for lift in self.lifts:
            thread = threading.Thread(target=self.move_lift, args=(lift,))
            thread.start()

    def move_lift(self, lift):
        while True:
            if lift.position < self.floor_count - 1:
                lift.move('up')
            elif lift.position > 0:
                lift.move('down')
            time.sleep(1)

skyscraper = Skyscraper()
for i in range(5):
    skyscraper.add_lift(f"Lift {i+1}")

skyscraper.start_simulation()
```

This code creates a `Lift` class to represent individual lifts, and a `Skyscraper` class to manage the simulation. The `start_simulation` method starts all the lifts moving up from floor 0. You can adjust the number of floors and lifts according to your needs.

